  /** Lift the yard's name card this far above the bottom safe area (room for the client's HUD). */
  cardBottomPx?: number;
  /** A cat was tapped (its name card opened) or the card closed (null). */
  onSelect?(id: string | null): void;
  /** SELECT on the name card of a cat that is not the active one. */
  onChoose?(id: string): void;
  /** The cat sent by `feed` reached the bowls and started eating. */
  onEating?(id: string): void;
  /** The cat finished eating (after `feed`). */
  onFed?(id: string): void;
  /** A cat's sheet failed to load. */
  onSheetError?(id: string): void;
