export interface HomeYardModule {
  HOME_YARD_API_VERSION: number;
  createHomeYard(el: HTMLElement, options: HomeYardOptions): HomeYardAPI;
}

/** A loaded module the client can use: the right shape and the same API version. */
export function isHomeYardModule(value: unknown): value is HomeYardModule {
  if (!value || typeof value !== 'object') return false;
  const m = value as Partial<HomeYardModule>;
  return m.HOME_YARD_API_VERSION === HOME_YARD_API_VERSION && typeof m.createHomeYard === 'function';
}

/**
 * The cats HOME shows: unique ids with a sheet, at most `max`, the active cat always first, then
 * the newest (by createdAt, else their order).
 */
export function pickHomeYardCats(cats: readonly HomeYardCat[], max: number = HOME_YARD_MAX_CATS): HomeYardCat[] {
  const seen = new Set<string>();
  const usable: { cat: HomeYardCat; order: number }[] = [];
  cats.forEach((cat, order) => {
    if (!cat || !cat.id || !cat.sheetUrl || seen.has(cat.id)) return;
    seen.add(cat.id);
    usable.push({ cat, order });
  });
  const time = (c: HomeYardCat) => {
    const t = c.createdAt ? Date.parse(c.createdAt) : NaN;
    return Number.isFinite(t) ? t : -Infinity;
  };
  usable.sort((a, b) => {
    if (a.cat.active !== b.cat.active) return a.cat.active ? -1 : 1;
    const ta = time(a.cat), tb = time(b.cat);
    if (ta !== tb) return tb > ta ? 1 : -1;
    return a.order - b.order;
  });
  const cap = Math.max(1, Math.floor(max));
  return usable.slice(0, cap).map((u) => u.cat);
}

/** Whether two cat lists hold the same ids (in any order): then the yard updates in place. */
export function sameHomeYardIds(a: readonly HomeYardCat[], b: readonly HomeYardCat[]): boolean {
  if (a.length !== b.length) return false;
  const ids = new Set(a.map((c) => c.id));
  return b.every((c) => ids.has(c.id));
}
